  const cam=G.cam;const fwd=new THREE.Vector3(0,0,-1).applyEuler(new THREE.Euler(P.pitch*0.6,P.yaw,0,'YXZ'));const dist=o.sz>=3?1.6:(o.sz>=2?1.1+o.r*0.6:0.75+o.r*0.4);const down=o.sz>=2?0.5:0.35;
  if(S.set.tp)_tmpV.set(P.pos.x,P.pos.y+P.eye,P.pos.z);else _tmpV.copy(cam.position);_tmpV.addScaledVector(fwd,dist);_tmpV.y-=down+ (o.sz>=2?0:0)+(P.crouch?0.1:0);
