  const consider=(kind,ref,p,r,maxD,label)=>{const to=_tmpV.copy(p).sub(cam.position);const d=to.length();if(d>maxD)return;const along=to.dot(fwd);if(along<0)return;const perp=Math.sqrt(Math.max(0,d*d-along*along));const tol=r+0.12+0.1*d;if(perp<tol){const score=perp/tol+d*0.05;if(!best||score<best.score)best={kind,ref,dist:d,label,score};}};
