  {const sg=m.specials&&m.specials.sig;if(sg&&!sg.done){for(const g of sg.gens){if(g.on&&g.k===P.k)consider('siggen',g,new THREE.Vector3(g.x,layerY(g.k)+0.8,g.z),0.9,3,'Hold E · Shut down generator ('+sigFloor(g.k)+')');}if(sg.term&&sg.term.k===P.k)consider('sigterm',sg.term,new THREE.Vector3(sg.term.x,layerY(0)+0.8,sg.term.z),0.8,3,sg.term.read?'Terminal · order noted':'Hold E · Read the terminal');}}
