function hasKey(){for(const id of P.pockets){const o=G.objById[id];if(o&&o.curse==='redkey')return true;}const h=P.hands&&G.objById[P.hands];return !!(h&&h.curse==='redkey');}
function interact(){if(P.dead)return;const t=lookTarget();if(!t)return;
  if(t.kind==='obj')grabObj(t.ref);
  else if(t.kind==='door')toggleDoor(t.ref);
  else if(t.kind==='doc')readDoc(t.ref);
  else if(t.kind==='hatch'){if(!t.ref.found){t.ref.found=true;toast('🔧 Emergency hatch found — leads to the yard');if(mpHost())bcast({t:'ev',k:'hatch'});else sendAct({k:'hatch'});}else{useHatch();}}
  else if(t.kind==='elev')useElevator();
  else if(t.kind==='van'){if(mpHost()||!MP.on)startDepart();}
  else if(t.kind==='stack'){if(mpHost())stackReveal(t.ref,P.id);else sendAct({k:'stack',id:t.ref.id});}
  else if(t.kind==='mimic'){if(mpHost())mimicTrigger(t.ref,P.id);else sendAct({k:'mimic',id:t.ref.id});}
}
function holdInteract(dt){/* E held: generator/terminal/beacon/revive */const t=lookTarget();if(!t||!(held('interact')||GP.use)){P.useT=0;P.useTarget=null;hidePrompt2();return;}
  if(['gen','term','beac','revive','siggen','sigterm'].indexOf(t.kind)<0){P.useT=0;return;}
  if(P.useTarget!==t.ref){P.useT=0;P.useTarget=t.ref;}
  const need=t.kind==='gen'?6:t.kind==='term'?7:t.kind==='beac'?5:t.kind==='siggen'?6:t.kind==='sigterm'?3:4;P.useT+=dt;if(t.kind==='siggen'){emitNoise(P.pos,P.k,0.9,'machine');if(Math.random()<dt*6)Aud.tone(60+Math.random()*40,0.1,'sawtooth',0.08,null,{lp:300});}
  if(t.kind==='gen'){emitNoise(P.pos,P.k,0.9,'machine');if(Math.random()<dt*6)Aud.tone(80+Math.random()*60,0.1,'sawtooth',0.08,null,{lp:400});}
  if(t.kind==='term'&&Math.random()<dt*4)Aud.tone(1200+Math.random()*800,0.05,'square',0.04);
  $('prompt').textContent=t.label+' '+Math.round(P.useT/need*100)+'%';
  if(P.useT>=need){P.useT=0;if(t.kind==='gen')doPower();else if(t.kind==='term')doTerminal();else if(t.kind==='beac')doBeacon();else if(t.kind==='revive')doRevive(t.ref);else if(t.kind==='siggen')doSigGen(t.ref);else if(t.kind==='sigterm')doSigTerm();}
}
